INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die AND-Operation nötig, um die Netzwerkadresse zu finden?', 2, '[{"text": "Ja", "correct": true, "because": "Trennt Netzwerkanteil"}, {"text": "Nein", "correct": false, "because": "Kern der Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ergibt 192.168.1.10 AND 255.255.255.0?', 3, '[{"text": "192.168.1.0", "correct": true, "because": "Netzwerkanteil bleibt"}, {"text": "192.168.1.10", "correct": false, "because": "Hostanteil wird 0"}, {"text": "255.255.255.0", "correct": false, "because": "Maske, nicht Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AND setzt Hostbits auf 0. b) AND verändert die Maske.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maske bleibt konstant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der AND-Operation?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Erster Operand"}, {"text": "Subnetzmaske", "correct": false, "because": "Zweiter Operand"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 1 AND 1 immer 1 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Logische Regel"}, {"text": "Nein", "correct": false, "because": "Falsche Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis hat 11000000 AND 11111111?', 3, '[{"text": "11000000", "correct": true, "because": "Bits bleiben bei 1"}, {"text": "00000000", "correct": false, "because": "Nur bei 0 AND 1"}, {"text": "11111111", "correct": false, "because": "Maske, nicht Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente brauche ich für die AND-Operation?', 5, '[{"text": "IP-Adresse", "correct": true, "because": "Erster Operand"}, {"text": "Subnetzmaske", "correct": true, "because": "Zweiter Operand"}, {"text": "Portnummer", "correct": false, "because": "Nicht relevant"}, {"text": "Protokolltyp", "correct": false, "because": "Netzwerkebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) AND findet den Netzwerkanteil. b) AND vergrößert die Adresse. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist technisch falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Binärberechnung?', 4, '[{"text": "Bitweise Logik", "correct": false, "because": "Kern der AND-Operation"}, {"text": "Maskenbits", "correct": false, "because": "Definiert Netz"}, {"text": "Grafische Darstellung", "correct": true, "because": "Nur zur Visualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 0 AND 1 immer 0?', 2, '[{"text": "Ja", "correct": true, "because": "Logische Regel"}, {"text": "Nein", "correct": false, "because": "Falsche Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ergibt 10.0.0.5 AND 255.255.255.240?', 4, '[{"text": "10.0.0.0", "correct": true, "because": "Netzwerkanteil bleibt"}, {"text": "10.0.0.5", "correct": false, "because": "Hostbits werden 0"}, {"text": "255.255.255.240", "correct": false, "because": "Maske, nicht Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass AND die Hostadresse findet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Findet Netzwerkadresse"}, {"text": "Ja", "correct": false, "because": "Falsche Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der AND-Operation?', 3, '[{"text": "Bitgenauigkeit", "correct": true, "because": "Sichert korrektes Ergebnis"}, {"text": "Schnelligkeit", "correct": false, "because": "Präzision zählt"}, {"text": "Rundung", "correct": false, "because": "Keine Dezimalwerte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AND nutzt die Maske. b) AND findet die Broadcast-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse liefert die AND-Operation?', 5, '[{"text": "Netzwerkadresse", "correct": true, "because": "Hostbits auf 0"}, {"text": "Subnetzgrenze", "correct": true, "because": "Definiert Netz"}, {"text": "Hostadresse", "correct": false, "because": "Nicht isoliert"}, {"text": "Gateway", "correct": false, "because": "Spezifische Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Binärberechnung unwichtig?', 3, '[{"text": "IP-Bits", "correct": false, "because": "Erster Operand"}, {"text": "Maskenbits", "correct": false, "because": "Zweiter Operand"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergibt 1111 AND 1100 immer 1100?', 3, '[{"text": "Ja", "correct": true, "because": "Nur 1 AND 1 bleibt 1"}, {"text": "Nein", "correct": false, "because": "Korrekte Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 172.16.1.1 AND 255.255.0.0 172.16.0.0 ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "Netzwerkanteil bleibt"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis hat 10101010 AND 11110000?', 4, '[{"text": "10100000", "correct": true, "because": "Nur übereinstimmende 1er"}, {"text": "11110000", "correct": false, "because": "Maske, nicht Ergebnis"}, {"text": "00001010", "correct": false, "because": "Falsche Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die AND-Operation?', 3, '[{"text": "Netzwerktrennung", "correct": true, "because": "Isoliert Netzanteil"}, {"text": "Hostzählung", "correct": false, "because": "Nicht primär"}, {"text": "Maskenerstellung", "correct": false, "because": "Maske ist Voraussetzung"}]');
